70	struct mpu_state mpu_state;
71	
72	struct mpu_region {
73		u_int	base;			/* Aligned to 2^log2. */
74		u_int	log2;			/* Size as a power of two. */
75		u_int	attrs;			/* RASR AP and XN bits. */
76	};
77	
78	/*
79	 * The boot ROM is 16 KB at address 0 (datasheet 2.8); the two window
80	 * regions tile USER_DATA_SIZE, which the static assertion below pins.
81	 */
82	#define	MPU_ROM_LOG2		14
83	#define	MPU_USER_LOW_LOG2	17
84	#define	MPU_USER_HIGH_LOG2	14
85	
86	_Static_assert((1UL << MPU_USER_LOW_LOG2) + (1UL << MPU_USER_HIGH_LOG2) ==
87	    USER_DATA_SIZE, "the two MPU window regions must tile USER_DATA_SIZE");
88	_Static_assert((USER_DATA_START & ((1UL << MPU_USER_LOW_LOG2) - 1)) == 0,
89	    "USER_DATA_START must be aligned to the low window region");
90	
91	static const struct mpu_region mpu_map[] = {
92		{ 0x00000000UL, MPU_ROM_LOG2, MPU_AP_RO },
93		{ USER_DATA_START, MPU_USER_LOW_LOG2, MPU_AP_RW },
94		{ USER_DATA_START + (1UL << MPU_USER_LOW_LOG2), MPU_USER_HIGH_LOG2,
95		    MPU_AP_RW },
96	};
97	#define	MPU_NMAP	(sizeof mpu_map / sizeof mpu_map[0])
98	
99	/*
100	 * Write one region through RBAR with VALID set, which selects the region
101	 * and sets RNR in the same write (table 116), then its RASR; return 1 when
102	 * both read back as written.
103	 */
104	static int
105	mpu_program(u_int n, const struct mpu_region *r)
106	{
107		u_int rbar, rasr;
108	
109		rbar = (r->base & MPU_RBAR_ADDR_MASK) | MPU_RBAR_VALID |
110		    (n & MPU_RBAR_REGION_MASK);
111		rasr = r->attrs | MPU_RASR_SIZE(r->log2) | MPU_RASR_ENABLE;
112	
113		MPU_REG32(MPU_RBAR) = rbar;
114		MPU_REG32(MPU_RASR) = rasr;
115		arm_dsb();
116	
117		/* VALID always reads as zero; RNR reads back through REGION. */
118		return MPU_REG32(MPU_RNR) == n &&
119		    MPU_REG32(MPU_RBAR) == ((r->base & MPU_RBAR_ADDR_MASK) | n) &&
120		    MPU_REG32(MPU_RASR) == rasr;
121	}
122	
123	void
124	mpu_init(void)
125	{
126		u_int n;
127	
128		mpu_state.type = MPU_REG32(MPU_TYPE);
129		mpu_state.nregions = (mpu_state.type & MPU_TYPE_DREGION_MASK) >>
130		    MPU_TYPE_DREGION_SHIFT;
131		mpu_state.programmed = 0;
132		mpu_state.ctrl = 0;
133		if (mpu_state.nregions < MPU_NMAP)
134			return;
135	
136		/*
137		 * Program with the MPU disabled, as the ARMv6-M ARM B3.5.4 orders
138		 * it, then enable with DSB and ISB so no access after the enable is
139		 * checked against the old map.
140		 */
141		MPU_REG32(MPU_CTRL) = 0;
142		arm_dsb();
143		for (n = 0; n < MPU_NMAP; n++)
144			mpu_state.programmed += mpu_program(n, &mpu_map[n]);
145		for (; n < mpu_state.nregions; n++) {
146			MPU_REG32(MPU_RBAR) = MPU_RBAR_VALID | n;
147			MPU_REG32(MPU_RASR) = 0;
148		}
149		if (mpu_state.programmed != MPU_NMAP) {
150			mpu_state.ctrl = MPU_REG32(MPU_CTRL);
151			return;
152		}
153		MPU_REG32(MPU_CTRL) = MPU_CTRL_PRIVDEFENA | MPU_CTRL_ENABLE;
154		arm_dsb();
155		arm_isb();
156		mpu_state.ctrl = MPU_REG32(MPU_CTRL);
157	}
158	
159	/*
160	 * One console line after the cpu: banner, stating what the registers read
161	 * back rather than what was written; the Renode gate asserts it.
162	 */
163	void
164	mpu_identify(void)
165	{
166		if (mpu_state.nregions == 0) {
167			printf("mpu: MPU_TYPE 0x%08x reports no regions, protection off\n",
168			    mpu_state.type);
169			return;
170		}
171		printf("mpu: %u regions, %u programmed, MPU_CTRL 0x%x: ",
172		    mpu_state.nregions, mpu_state.programmed, mpu_state.ctrl);
173		if (mpu_state.ctrl & MPU_CTRL_ENABLE)
174			printf("rom %uK r-x, user %uK rwx\n",
175			    (1U << MPU_ROM_LOG2) / 1024, USER_DATA_SIZE / 1024);
176		else
177			printf("protection off\n");
178	}
179	
180	int
181	mpu_sysctl(int *name, u_int namelen, void *oldp, size_t *oldlenp, void *newp,
182	    size_t newlen)
183	{
184		int v;
185	
186		(void)newlen;
187		if (namelen != 1)
188			return ENOTDIR;
189	
190		switch (name[0]) {
191		case CPU_MPU_ENABLE:
192			v = (mpu_state.ctrl & MPU_CTRL_ENABLE) != 0;
193			break;
194		case CPU_MPU_CTRL:
195			v = mpu_state.ctrl;
196			break;
197		case CPU_MPU_NREGIONS:
198			v = mpu_state.nregions;
199			break;
200		case CPU_MPU_SEPARATE:
201			v = (mpu_state.type & MPU_TYPE_SEPARATE) != 0;
202			break;
203		case CPU_MPU_PROGRAMMED:
204			v = mpu_state.programmed;
205			break;
206		default:
207			return EOPNOTSUPP;
208		}
209		return sysctl_rdstruct(oldp, oldlenp, newp, &v, sizeof v);
210	}
